<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'; import AppShell from '@/components/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import EmptyState from '@/components/EmptyState.vue'; import { useEdgeStore } from '@/stores/edge'; import { formatLastSeen } from '@/utils/status'
const edge = useEdgeStore(); const busy = ref(new Set<string>()); let timer: ReturnType<typeof setInterval> | undefined
async function refresh() { try { await edge.refresh() } catch {} }; async function act(nodeId: string, action: 'authorize' | 'revoke') { busy.value = new Set(busy.value).add(nodeId); try { await edge[action](nodeId) } finally { const next = new Set(busy.value); next.delete(nodeId); busy.value = next } }
onMounted(() => { refresh(); timer = setInterval(refresh, 5000) }); onUnmounted(() => { if (timer) clearInterval(timer) })
</script>
<template><AppShell><template #title>节点</template><PageHeader title="节点管理" :refreshing="edge.loading" @refresh="refresh" /><EmptyState v-if="!edge.nodes.length" text="暂无注册节点" /><view v-else class="list"><view v-for="node in edge.nodes" :key="node.nodeId" class="node"><view class="main"><text class="name">{{ node.nodeId }}</text><text class="meta">{{ node.host }}:{{ node.port }} · {{ node.tools?.length || 0 }} 个工具</text><text class="meta">{{ formatLastSeen(node.lastSeen) }}</text></view><view class="actions"><StatusBadge :status="node.status" /><button v-if="node.status === 'pending'" class="authorize" :disabled="busy.has(node.nodeId)" @tap="act(node.nodeId, 'authorize')">{{ busy.has(node.nodeId) ? '…' : '授权' }}</button><button v-if="node.status === 'online' || node.status === 'offline'" class="revoke" :disabled="busy.has(node.nodeId)" @tap="act(node.nodeId, 'revoke')">{{ busy.has(node.nodeId) ? '…' : '撤销' }}</button></view></view></view></AppShell></template>
<style scoped>.list { display:flex; flex-direction:column; gap:16rpx; }.node { display:flex; justify-content:space-between; align-items:center; gap:14rpx; background:#101a2d; border:1rpx solid #1a2a43; border-radius:22rpx; padding:24rpx; }.main { min-width:0; display:flex; flex-direction:column; gap:8rpx; }.name { font-weight:700; font-size:27rpx; }.meta { color:#75809a; font-size:20rpx; }.actions { display:flex; flex-direction:column; align-items:flex-end; gap:14rpx; }.actions button { border:0; border-radius:12rpx; font-size:21rpx; padding:9rpx 18rpx; }.authorize { background:#55d6be22; color:#55d6be; }.revoke { background:#ff6b7a22; color:#ff6b7a; }.actions button[disabled] { opacity:.5; }</style>
